#!/usr/bin/env python3
"""Golden vectors for the Java ports, generated by the Python models that were verified against the ORIGINAL AND2011 code.
Writes work/golden/*.txt.  Hash = FNV-1a 32 (hl4.test.Fnv).
Usage: python3 tools/j2me_golden.py <kind> <res dir> [out dir]       kinds: des | blit
"""
import os
import struct
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))


def fnv_bytes(b):
    h = 0x811c9dc5
    for c in b:
        h = ((h ^ c) * 0x01000193) & 0xffffffff
    return h


def fnv_shorts_le(b):
    return fnv_bytes(b)          # RGB565 little-endian bytes: low byte then high byte == hl4.test.Fnv.shorts


def gen_des(res, out):
    import hl4des
    lines = []
    for root, _, fs in sorted(os.walk(res)):
        for f in sorted(fs):
            p = os.path.join(root, f)
            rel = os.path.relpath(p, res).replace(os.sep, '/')
            if hl4des.is_des_resource(rel):
                raw = open(p, 'rb').read()
                lines.append('%s %08x' % (rel, fnv_bytes(hl4des.decrypt(raw))))
    open(os.path.join(out, 'des.txt'), 'w').write('\n'.join(lines) + '\n')
    print('des.txt', len(lines), 'files')


def gen_blit(res, out, every=7):
    """Cases of the DM_DrawImg self-test (tools/dm_blit.py) sampled every `every`-th case; expected = CRC-32 of the 240x400 frame (BG 0x1234)."""
    import zlib
    import dm_blit
    import gbm
    FW, FH, BG = dm_blit.FW, dm_blit.FH, dm_blit.BG
    imgs = []
    for (w, h, t) in ((5, 3, 0x0c), (4, 6, 0x0c), (5, 3, 0x0b), (7, 5, 0x0b), (1, 1, 0x0c), (16, 16, 0x0c)):
        imgs.append(('syn %d %d %d' % (w, h, t), dm_blit._synthetic(w, h, t)))
    real = []
    for root, _, fs in sorted(os.walk(res)):
        for fn in sorted(fs):
            p = os.path.join(root, fn)
            b = open(p, 'rb').read()
            if gbm.is_container(b):
                for k, body in enumerate(gbm.parse_container(b)):
                    if len(body) >= 9 and gbm.header(body)[1] <= 120 and gbm.header(body)[2] <= 120:
                        real.append(('res %s %d' % (os.path.relpath(p, res).replace(os.sep, '/'), k), body))
                        break
    step = max(1, len(real) // 12)
    imgs += real[::step][:12]
    open(os.path.join(out, 'blit_images.txt'), 'w').write('\n'.join(n for n, _ in imgs) + '\n')
    clips = [(0, 0, FW, FH), (20, 30, 100, 90), (50, 50, 52, 52), (0, 0, 8, 8), (232, 392, 240, 400)]
    anchors = [0, 0x10, 0x20, 0x02, 0x04, 0x12, 0x24, 0x14, 0x22, 0x30, 0x06]
    combos = [(f, r) for f in (0, 1, 2) for r in (0, 90, 180, 270)] + [(3, 0), (3, 90), (3, 270)] + [(0, 45), (1, 360)]
    bg = struct.pack('<H', BG) * (FW * FH)
    lines = []
    k = 0
    for ii, (name, body) in enumerate(imgs):
        iw, ih, rows = gbm.decode(body)
        subs = [(0, 0, iw, ih)]
        if iw > 2 and ih > 2:
            subs.append((1, 1, iw - 2, ih - 1))
        for (sx, sy, w, h) in subs:
            for clip in clips:
                for (flip, rot) in combos:
                    for anc in anchors:
                        xs = {clip[0] - w - 1, clip[0] - w, clip[0] - 1, clip[0], clip[0] + 1, (clip[0] + clip[2]) // 2, clip[2] - 1, clip[2], 3, -7}
                        ys = {clip[1] - h - 1, clip[1] - h, clip[1] - 1, clip[1], clip[1] + 1, (clip[1] + clip[3]) // 2, clip[3] - 1, clip[3], 5, -9}
                        for x in sorted(xs)[::2] + sorted(xs)[1::4]:
                            for y in sorted(ys)[::2] + sorted(ys)[1::4]:
                                pl = dm_blit.plan(x, y, w, h, sx, sy, flip, rot, anc, clip)
                                if pl is not None and (pl[2] <= 0 or pl[3] <= 0):
                                    continue
                                k += 1
                                if k % every:
                                    continue
                                fb = bytearray(bg)
                                dm_blit.draw(fb, FW, FH, clip, rows, x, y, w, h, sx, sy, flip, rot, anc)
                                lines.append('%d %d %d %d %d %d %d %d %d %d %d %d %d %d %08x' % (
                                    ii, sx, sy, w, h, clip[0], clip[1], clip[2], clip[3], flip, rot, anc, x, y, zlib.crc32(bytes(fb)) & 0xffffffff))
    open(os.path.join(out, 'blit.txt'), 'w').write('\n'.join(lines) + '\n')
    print('blit.txt', len(lines), 'cases of', k)


if __name__ == '__main__':
    kind, res = sys.argv[1], sys.argv[2]
    out = sys.argv[3] if len(sys.argv) > 3 else os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'work', 'golden')
    os.makedirs(out, exist_ok=True)
    if kind == 'des':
        gen_des(res, out)
    elif kind == 'blit':
        gen_blit(res, out, int(sys.argv[4]) if len(sys.argv) > 4 else 7)
